        HELPER_ASSERT_SUCCESS(r.set_url("/api/v1/clients/", false));

        SrsHttpAuthMux auth(&s);
        HELPER_ASSERT_SUCCESS(auth.initialize(true, "admin", "admin"));

        HELPER_ASSERT_SUCCESS(auth.serve_http(&w, &r));
        EXPECT_EQ(401, w.w->status_);
